export function workspaceRoute(hash){const value=hash.replace(/^#/,'')||'home';if(['demo','demo/trend','demo/full','demo/overview'].includes(value))return {mode:'demo',page:'overview'};return value.startsWith('demo/')?{mode:'demo',page:value.slice(5)||'overview'}:{mode:'user',page:value};}
export function createWorkspaces(makeDemo){let mode='user';const empty=()=>({rows:[],importQuality:null,previousReport:null,analysisCache:null,reportCache:null,filter:'all',dataSource:'',updatedAt:null});const states={user:empty(),demo:null};return {switchTo(next,current){states[mode]=current;if(!states[next])states[next]={...empty(),rows:makeDemo(),dataSource:'Demo dataset',updatedAt:new Date()};mode=next;return states[next]},get mode(){return mode}};}
